struct Node {
  int value = 0;
  std::unique_ptr<Node> next;
};

[[nodiscard]] std::unique_ptr<Node> reverse(std::unique_ptr<Node> head) {
  std::unique_ptr<Node> reversed;  // the part already reversed
  while (head) {
    std::unique_ptr<Node> rest = std::move(head->next);  // detach the rest first
    head->next = std::move(reversed);                    // turn the front node around
    reversed = std::move(head);                          // it is now the front of the reversed part
    head = std::move(rest);
  }
  return reversed;
}

[[nodiscard]] std::unique_ptr<Node> make_list(std::span<const int> values) {
  std::unique_ptr<Node> head;
  for (const int v : values | std::views::reverse) head = std::make_unique<Node>(v, std::move(head));
  return head;
}

[[nodiscard]] std::string show(const Node* node) {
  std::string out;
  for (; node; node = node->next.get()) out += std::format("{}{}", out.empty() ? "" : " ", node->value);
  return "[" + out + "]";
}

int main() {
  const std::vector<int> four{1, 2, 3, 4};
  const std::vector<int> one{7};
  std::cout << show(reverse(make_list(four)).get()) << '\n';
  std::cout << show(reverse(make_list(one)).get()) << '\n';
  std::cout << show(reverse(nullptr).get()) << '\n';
}

