// Inserts n pseudo-random values so the container stays sorted, and returns the time it took.
template <typename Container>
[[nodiscard]] double sorted_inserts_ms(std::int64_t n) {
  std::mt19937 gen{7};
  Container c;
  const auto start = std::chrono::steady_clock::now();
  for (std::int64_t i = 0; i < n; ++i) {
    const auto x = static_cast<std::int64_t>(gen());
    c.insert(std::ranges::find_if(c, [x](std::int64_t e) { return e > x; }), x);
  }
  const std::chrono::duration<double, std::milli> took = std::chrono::steady_clock::now() - start;
  return took.count();
}

int main() {
  constexpr std::array<std::int64_t, 2> sizes{1'000, 10'000};
  for (const std::int64_t n : sizes)
    std::cout << std::format("n = {:>6}: vector {:8.1f} ms, list {:8.1f} ms\n", n,
                             sorted_inserts_ms<std::vector<std::int64_t>>(n),
                             sorted_inserts_ms<std::list<std::int64_t>>(n));
}

