struct Node {
  int value = 0;
  std::unique_ptr<Node> next;
};

// Removes every node holding value, and returns how many it removed.
std::int64_t remove_all(std::unique_ptr<Node>& head, int value) {
  Node dummy{.value = 0, .next = std::move(head)};  // gives the first node a predecessor
  std::int64_t removed = 0;
  Node* prev = &dummy;  // the node before the one being looked at
  while (prev->next) {
    if (prev->next->value == value) {
      std::unique_ptr<Node> rest = std::move(prev->next->next);  // take the rest out of the node first
      prev->next = std::move(rest);                              // then unlink the node, which destroys it
      ++removed;
    } else {
      prev = prev->next.get();
    }
  }
  head = std::move(dummy.next);
  return removed;
}

// The middle node; the second of the two middle nodes for an even count; null for an empty list.
[[nodiscard]] const Node* middle(const Node* head) {
  const Node* slow = head;
  const Node* fast = head;
  while (fast && fast->next) {
    slow = slow->next.get();
    fast = fast->next->next.get();
  }
  return slow;
}

[[nodiscard]] std::unique_ptr<Node> make_list(std::span<const int> values) {
  std::unique_ptr<Node> head;
  for (const int v : values | std::views::reverse) head = std::make_unique<Node>(v, std::move(head));
  return head;
}

[[nodiscard]] std::string show(const Node* node) {
  std::string out;
  for (; node; node = node->next.get()) out += std::format("{}{}", out.empty() ? "" : " ", node->value);
  return "[" + out + "]";
}

int main() {
  const std::vector<int> values{2, 1, 2, 3, 2};
  std::unique_ptr<Node> list = make_list(values);
  const std::int64_t removed = remove_all(list, 2);
  std::cout << std::format("removed {}, left {}\n", removed, show(list.get()));

  for (const std::vector<int>& v : {std::vector{1, 2, 3, 4, 5}, std::vector{1, 2, 3, 4, 5, 6}, std::vector<int>{}}) {
    const std::unique_ptr<Node> l = make_list(v);
    const Node* m = middle(l.get());
    std::cout << std::format("middle of {}: {}\n", show(l.get()), m ? std::to_string(m->value) : "none");
  }
}

