struct Node {
  int value = 0;
  std::optional<std::ptrdiff_t> next;  // index of the next node in the same vector, or no value at the end
};

using Link = std::optional<std::ptrdiff_t>;

[[nodiscard]] Link step(std::span<const Node> nodes, Link at) { return at ? nodes[*at].next : std::nullopt; }

[[nodiscard]] Link cycle_start(std::span<const Node> nodes, Link head) {
  Link slow = head;
  Link fast = head;
  while (true) {
    slow = step(nodes, slow);
    fast = step(nodes, step(nodes, fast));
    if (!fast) return std::nullopt;  // fast fell off the end: the list ends
    if (slow == fast) break;         // both are in the cycle, at the same node
  }
  slow = head;
  while (slow != fast) {
    slow = step(nodes, slow);
    fast = step(nodes, fast);
  }
  return slow;
}

// Nodes 0 to n-1 linked in order; the last one links to loop_to.
[[nodiscard]] std::vector<Node> chain(std::span<const int> values, Link loop_to) {
  std::vector<Node> nodes;
  for (std::ptrdiff_t i = 0; i < std::ssize(values); ++i) nodes.push_back({.value = values[i], .next = i + 1});
  if (!nodes.empty()) nodes.back().next = loop_to;
  return nodes;
}

[[nodiscard]] std::string show(Link at) { return at ? std::format("index {}", *at) : "no cycle"; }

int main() {
  const std::vector<int> five{3, 1, 4, 1, 5};
  const std::vector<int> one{9};
  std::cout << "back to 2:  " << show(cycle_start(chain(five, 2), 0)) << '\n';
  std::cout << "no cycle:   " << show(cycle_start(chain(five, std::nullopt), 0)) << '\n';
  std::cout << "self loop:  " << show(cycle_start(chain(one, 0), 0)) << '\n';
  std::cout << "back to 0:  " << show(cycle_start(chain(five, 0), 0)) << '\n';
  std::cout << "empty list: " << show(cycle_start({}, std::nullopt)) << '\n';
}

