struct Node {
  int value = 0;
  std::unique_ptr<Node> next;
};

[[nodiscard]] std::unique_ptr<Node> merge(std::unique_ptr<Node> a, std::unique_ptr<Node> b) {
  std::unique_ptr<Node> head;
  std::unique_ptr<Node>* tail = &head;  // the link that receives the next node
  while (a && b) {
    std::unique_ptr<Node>& smaller = b->value < a->value ? b : a;  // equal values take from a
    *tail = std::move(smaller);          // the front node moves to the end of the result
    smaller = std::move((*tail)->next);  // its old list continues from the node after it
    tail = &(*tail)->next;
  }
  *tail = a ? std::move(a) : std::move(b);  // one list is empty; the other is appended whole
  return head;
}

[[nodiscard]] std::unique_ptr<Node> make_list(std::span<const int> values) {
  std::unique_ptr<Node> head;
  for (const int v : values | std::views::reverse) head = std::make_unique<Node>(v, std::move(head));
  return head;
}

[[nodiscard]] std::string show(const Node* node) {
  std::string out;
  for (; node; node = node->next.get()) out += std::format("{}{}", out.empty() ? "" : " ", node->value);
  return "[" + out + "]";
}

int main() {
  const std::vector<std::pair<std::vector<int>, std::vector<int>>> cases{
      {{1, 3, 5}, {2, 4, 6}}, {{1, 2, 4}, {1, 3, 4}}, {{}, {1, 2}}, {{}, {}}, {{5}, {1, 2, 3}}};
  for (const auto& [a, b] : cases) std::cout << show(merge(make_list(a), make_list(b)).get()) << '\n';
}

