struct Node {
  int value = 0;
  std::unique_ptr<Node> next;
};

std::optional<int> remove_nth_from_end(std::unique_ptr<Node>& head, std::ptrdiff_t n) {
  if (n < 1) return std::nullopt;
  const Node* lead = head.get();
  for (std::ptrdiff_t i = 0; i < n; ++i) {
    if (!lead) return std::nullopt;  // fewer than n nodes
    lead = lead->next.get();
  }
  std::unique_ptr<Node>* link = &head;  // stays n nodes behind lead
  while (lead) {
    lead = lead->next.get();
    link = &(*link)->next;
  }
  const int value = (*link)->value;
  std::unique_ptr<Node> rest = std::move((*link)->next);
  *link = std::move(rest);  // unlink and destroy the node
  return value;
}

[[nodiscard]] std::unique_ptr<Node> make_list(std::span<const int> values) {
  std::unique_ptr<Node> head;
  for (const int v : values | std::views::reverse) head = std::make_unique<Node>(v, std::move(head));
  return head;
}

[[nodiscard]] std::string show(const Node* node) {
  std::string out;
  for (; node; node = node->next.get()) out += std::format("{}{}", out.empty() ? "" : " ", node->value);
  return "[" + out + "]";
}

int main() {
  const std::vector<int> five{1, 2, 3, 4, 5};
  for (const std::ptrdiff_t n : {2, 5, 1, 6, 0}) {
    std::unique_ptr<Node> list = make_list(five);
    const std::optional<int> removed = remove_nth_from_end(list, n);
    std::cout << std::format("n = {}: removed {}, left {}\n", n, removed ? std::to_string(*removed) : "nothing",
                             show(list.get()));
  }
  const std::vector<int> one{7};
  std::unique_ptr<Node> single = make_list(one);
  const std::optional<int> removed = remove_nth_from_end(single, 1);
  std::cout << std::format("[7], n = 1: removed {}, left {}\n", removed.value(), show(single.get()));
}

