#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <utility>

struct Node {
  int value = 0;
  std::unique_ptr<Node> next;
};

// Owns a chain of nodes and destroys it one node at a time.
class List {
 public:
  List() = default;
  List(const List&) = delete;
  List& operator=(const List&) = delete;
  List(List&&) noexcept = default;
  List& operator=(List&& other) noexcept {
    clear();  // the defaulted version would destroy the old nodes recursively
    head_ = std::move(other.head_);
    return *this;
  }
  ~List() { clear(); }

  void push_front(int value) { head_ = std::make_unique<Node>(value, std::move(head_)); }

  void clear() noexcept {
    while (head_) {
      std::unique_ptr<Node> rest = std::move(head_->next);  // the first node's next is now empty,
      head_ = std::move(rest);                              // so destroying it goes no deeper
    }
  }

  [[nodiscard]] const Node* head() const { return head_.get(); }

 private:
  std::unique_ptr<Node> head_;
};

int main() {
  List list;
  for (int i = 0; i < 1'000'000; ++i) list.push_front(i);
  std::int64_t sum = 0;
  for (const Node* node = list.head(); node; node = node->next.get()) sum += node->value;
  std::cout << std::format("1000000 nodes, sum {}\n", sum);
  List moved = std::move(list);
  list = std::move(moved);
  std::cout << std::format("moved there and back, the head holds {}\n", list.head()->value);
}

